// ValidateConfig validates all fields in Config according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateConfig(m *Config) error {
	return ValidateConfigWithDepth(m, 0)
}

// ValidateConfigWithDepth validates Config and carries nested-message depth across
// generated package boundaries.
func ValidateConfigWithDepth(m *Config, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate ExternalHostnames (assert_max_size: 16)
	if len(m.ExternalHostnames) > 16 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ExternalHostnames exceeds max size of 16, got: %d", len(m.ExternalHostnames))
	}

	// Validate RootCa (assert_max_size: 4)
	if len(m.RootCa) > 4 {
		return protoerrors.NewErrMissingInvalidData(nil, "field RootCa exceeds max size of 4, got: %d", len(m.RootCa))
	}

	// Validate ExternalHostnames elements (default max size: 32768 bytes)
	for i, val := range m.ExternalHostnames {
		if len(val) > 32768 {
			return protoerrors.NewErrMissingInvalidData(nil, "field ExternalHostnames[%d] exceeds max size of 32768 bytes, got: %d", i, len(val))
		}
	}

	// Validate ExternalCertPem (default max size: 32768 bytes)
	if len(m.ExternalCertPem) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ExternalCertPem exceeds max size of 32768 bytes, got: %d", len(m.ExternalCertPem))
	}

	// Validate ExternalKeyPem (default max size: 32768 bytes)
	if len(m.ExternalKeyPem) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ExternalKeyPem exceeds max size of 32768 bytes, got: %d", len(m.ExternalKeyPem))
	}

	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	// Validate ExternalTlsMode enum value is known
	if _, ok := ExternalTlsMode_name[int32(m.ExternalTlsMode)]; !ok {
		return protoerrors.NewErrMissingInvalidData(nil, "field ExternalTlsMode has unknown enum value %d", int32(m.ExternalTlsMode))
	}

	// Validate TcpListener nested message
	if m.TcpListener != nil {
		if err := host.ValidateHostWithDepth(m.TcpListener, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field TcpListener validation failed")
		}
	}

	// Validate QuicListener nested message
	if m.QuicListener != nil {
		if err := host.ValidateHostWithDepth(m.QuicListener, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field QuicListener validation failed")
		}
	}

	// Validate RootCa nested messages
	for i, val := range m.RootCa {
		if err := x509.ValidateX509CertWithDepth(val, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field RootCa[%d] validation failed", i)
		}
	}

	// Validate HttpListener nested message
	if m.HttpListener != nil {
		if err := host.ValidateHostWithDepth(m.HttpListener, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field HttpListener validation failed")
		}
	}

	// Validate AcmeBackend nested message
	if m.AcmeBackend != nil {
		if err := host.ValidateHostWithDepth(m.AcmeBackend, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field AcmeBackend validation failed")
		}
	}

	return nil
}

