// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.HealthPollIntervalSeconds == 0 {
		dst.HealthPollIntervalSeconds = src.HealthPollIntervalSeconds
	}
	if !dst.EnableHttp {
		dst.EnableHttp = src.EnableHttp
	}
	if !dst.EnableHttp3 {
		dst.EnableHttp3 = src.EnableHttp3
	}
	if !dst.EnableGrpc {
		dst.EnableGrpc = src.EnableGrpc
	}
	if dst.TcpListener == nil {
		dst.TcpListener = src.TcpListener
	}
	if dst.QuicListener == nil {
		dst.QuicListener = src.QuicListener
	}
	if dst.ExternalTlsMode == 0 {
		dst.ExternalTlsMode = src.ExternalTlsMode
	}
	if len(dst.ExternalHostnames) == 0 {
		dst.ExternalHostnames = src.ExternalHostnames
	}
	if dst.ExternalCertPem == "" {
		dst.ExternalCertPem = src.ExternalCertPem
	}
	if dst.ExternalKeyPem == "" {
		dst.ExternalKeyPem = src.ExternalKeyPem
	}
	if len(dst.RootCa) == 0 {
		dst.RootCa = src.RootCa
	}
	if dst.HttpListener == nil {
		dst.HttpListener = src.HttpListener
	}
	if dst.AcmeBackend == nil {
		dst.AcmeBackend = src.AcmeBackend
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

// ============================================================
// Merge: PublicCaResponse
// ============================================================
// MergePublicCaResponse fills zero-valued fields in dst from src.
func MergePublicCaResponse(dst, src *PublicCaResponse) {
	if len(dst.Certs) == 0 {
		dst.Certs = src.Certs
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

// ============================================================
// Merge: GatewayConfigState
// ============================================================
// MergeGatewayConfigState fills zero-valued fields in dst from src.
func MergeGatewayConfigState(dst, src *GatewayConfigState) {
	if dst.Config == nil {
		dst.Config = src.Config
	} else if src.Config != nil {
		MergeConfig(dst.Config, src.Config)
	}
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

