// Merge: MapEmpty
// ============================================================
// MergeMapEmpty fills zero-valued fields in dst from src.
func MergeMapEmpty(dst, src *MapEmpty) {
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}
